export const config={id:'paper-city',title:'纸城入夜',subtitle:'A SMALL CITY, A LONG EVENING',description:'二十五栋折纸建筑组成暮光街区，调节夜色可改变窗光，太阳与电车缓慢移动。',category:'coding-motion',useCase:'城市主题片头、品牌叙事、建筑互动插画',accent:'#ef9d62',duration:20,parameter:{label:'暮色深度',min:0,max:100,step:1,value:62,unit:'%'}};
export function cityState(t,value){const dusk=Math.max(0,Math.min(100,value))/100;return {dusk,tramU:4.65,lightSweep:(Math.sin(t*Math.PI*2/config.duration)+1)/2,tram:(1-Math.cos(t*Math.PI*2/config.duration))/2,buildings:Array.from({length:25},(_,i)=>({u:i%5,v:Math.floor(i/5),height:48+((i*37+13)%110),lit:((i*17)%25)/25<dusk}))};}
function poly(c,pts,color){c.beginPath();pts.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.closePath();c.fillStyle=color;c.fill();}
function mix(a,b,p){return `rgb(${a.map((v,i)=>Math.round(v+(b[i]-v)*p)).join(',')})`;}
function label(c,s,x,y,size=12,color='#493e58'){c.font=`${size}px "Noto Sans CJK SC", ui-monospace, monospace`;c.fillStyle=color;c.fillText(s,x,y);}
export function render(c,{t,value,width,height}){c.save();c.scale(width/1200,height/800);const st=cityState(t,value),d=st.dusk;const bg=c.createLinearGradient(0,0,0,800);bg.addColorStop(0,mix([246,218,187],[29,36,64],d));bg.addColorStop(1,mix([244,233,214],[87,72,94],d));c.fillStyle=bg;c.fillRect(0,0,1200,800);const ink=d>.5?'#f5dfc7':'#493e58';label(c,'PAPER CITY / EDITION 02',48,52,13,ink);label(c,'纸城入夜',48,100,34,ink);label(c,'A SMALL CITY, A LONG EVENING',48,127,13,ink);
const sunX=780+Math.sin(t*Math.PI*2/config.duration)*130,sunY=180+d*160;c.fillStyle=mix([255,239,192],[243,176,131],d);c.beginPath();c.arc(sunX,sunY,53,0,Math.PI*2);c.fill();for(let i=0;i<5;i++){c.fillStyle=`rgba(255,230,200,${.08*(1-d)})`;c.fillRect(0,180+i*22,1200,3);}
const iso=(u,v,z=0)=>[600+(u-v)*71,370+(u+v)*35-z];poly(c,[[600,329],[1040,545],[600,763],[160,545]],'#292d4633');poly(c,[[600,307],[1040,525],[600,741],[160,525]],mix([204,173,154],[60,62,86],d));poly(c,[[160,525],[600,741],[600,755],[160,540]],'#5f566a');poly(c,[[600,741],[1040,525],[1040,540],[600,755]],'#393c54');
for(let i=0;i<6;i++){let a=iso(i-.5,-.5),b=iso(i-.5,4.5);c.strokeStyle='#ffe8bf33';c.setLineDash([3,8]);c.beginPath();c.moveTo(...a);c.lineTo(...b);c.stroke();a=iso(-.5,i-.5);b=iso(4.5,i-.5);c.beginPath();c.moveTo(...a);c.lineTo(...b);c.stroke();}c.setLineDash([]);
const sorted=[...st.buildings].sort((a,b)=>(a.u+a.v)-(b.u+b.v));for(const b of sorted){const {u,v,height:h}=b;const A=iso(u-.35,v-.35),B=iso(u+.35,v-.35),C=iso(u+.35,v+.35),D=iso(u-.35,v+.35);const top=p=>[p[0],p[1]-h];const illumination=Math.max(0,1-Math.abs((u+v)/8-st.lightSweep)*3);poly(c,[A,B,C,D].map(p=>[p[0]+h*.35,p[1]+h*.14]),'#161c3420');poly(c,[B,C,top(C),top(B)],mix([161,134,125],[49,58,81],d));poly(c,[D,C,top(C),top(D)],mix([222,185,151],[84,85,105],d));poly(c,[top(A),top(B),top(C),top(D)],mix([250,224,184],[136,124,134],d));poly(c,[top(A),top(B),[top(B)[0],top(B)[1]+5],[top(A)[0],top(A)[1]+5]],'#fff0d833');
for(let level=15;level<h-10;level+=20)for(let k=0;k<3;k++){const f=(k+1)/4;const x=D[0]+(C[0]-D[0])*f,y=D[1]+(C[1]-D[1])*f-level;c.fillStyle=b.lit?`rgba(255,211,131,${.65+illumination*.35})`:'#443f561f';poly(c,[[x,y],[x+7,y+3.5],[x+7,y+11],[x,y+7.5]],c.fillStyle);}}
const tram=iso(st.tramU,st.tram*5-.5);poly(c,[[tram[0]-13,tram[1]-13],[tram[0]+13,tram[1]],[tram[0]+13,tram[1]+10],[tram[0]-13,tram[1]-3]],'#ffca81');c.fillStyle='#fff1ba';c.beginPath();c.arc(tram[0]+13,tram[1]+5,3,0,Math.PI*2);c.fill();label(c,'暮色 / DUSK',982,75,12,ink);label(c,`${Math.round(value)}%`,982,116,32,ink);label(c,'A paper model of an imagined neighborhood.',48,772,13,ink);label(c,'LIGHT • LAYERS • TIME',940,772,12,ink);c.restore();}
